mapper.select:
select p.id, p.name, p.merchant_id, p.category_id, p.brand_id, p.main_image, p.status, p.deleted, p.update_time, b.name as brandName, c.name as categoryName, mp.shop_name as merchantName, sku_agg.min_price as minPrice, sku_agg.total_stock as totalStock, ifnull(sales_agg.sales, 0) as salesCount from product p left join merchant_profile mp on p.merchant_id = mp.user_id left join brand b on p.brand_id = b.id left join category c on p.category_id = c.id left join ( select product_id, min(price) as min_price, sum(stock) as total_stock from product_sku where deleted = 0 group by product_id ) sku_agg on p.id = sku_agg.product_id
left join ( select oi.product_id, SUM(oi.quantity) as sales from order_item oi left join `order` o on oi.order_id = o.id where o.status in (1, 3, 4) group by oi.product_id ) sales_agg on p.id = sales_agg.product_id
and p.deleted = #{dto.deleted}
and ( p.name like concat('%', #{dto.keyword}, '%') or c.name like concat('%', #{dto.keyword}, '%') or b.name like concat('%', #{dto.keyword}, '%') or mp.shop_name like concat('%', #{dto.keyword}, '%') )
and p.category_id = #{dto.categoryId}
and p.brand_id = #{dto.brandId}
and p.status = #{dto.status}
and p.merchant_id = #{dto.merchantId}
and mp.shop_name like concat('%',#{dto.merchantName},'%')
order by salesCount desc, p.create_time desc
order by minPrice asc, p.create_time desc
order by minPrice desc, p.create_time desc
order by p.create_time desc
order BY p.create_time desc

select name from product
where name = #{name}
and merchant_id = #{merchantId}

    and id != #{productId}

limit 1

select b.* from product p
left join brand b on p.brand_id = b.id
where p.id = #{productId}

select c.* from product p
left join category c on p.category_id = c.id
where p.id = #{productId}
